   338  static void *lex_multiline_string(struct lexer *lexer)
   339  {
   340      char *end = (peek(lexer) == '"') ? "\"\"\"" : "'''";
   341
   342      advance_n(lexer, strlen("'''") - 1);
   343
   344      do {
   345          if (!strncmp(lexer->pos, end, 3)) {
   346              emit(lexer, LEXEME_STRING);
   347              lexer->pos += 3;
   348
   349              return lex_config;
   350          }
   351      } while (next(lexer) != '\0');
   352
   353      return lex_error(lexer, "EOF while scanning multiline string");
   354  }
