   381  static void *lex_variable(struct lexer *lexer)
   382  {
   383      int chr;
   384
   385      advance_n(lexer, strlen("${") - 1);
   386
   387      do {
   388          chr = next(lexer);
   389
   390          if (chr == ':') {
   391              backup(lexer);
   392              emit(lexer, LEXEME_VARIABLE_DEFAULT);
   393              advance_n(lexer, strlen(":"));
   394              return lex_variable_default;
   395          }
   396
   397          if (chr == '}') {
   398              backup(lexer);
   399              emit(lexer, LEXEME_VARIABLE);
   400              advance_n(lexer, strlen("}"));
   401
   402              return lex_config;
   403          }
   404      } while (isvariable(chr));
   405
   406      return lex_error(lexer, "EOF while scanning for end of variable");
